import { expect, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("Documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
    // Background: signed in as a Northwind member with a draft vendor
    const member = await apiAs("member");
    const ownVendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Northwind Draft"), category: "software", contact_email: "ops@northwind-supply.com" },
    });
    expect(ownVendor.status(), await ownVendor.text()).toBe(201);
    expect((await ownVendor.json()).status).toBe("draft");

    // Arrange: a document that exists in the Globex tenant
    const globex = await apiAs("otherTenant");
    const globexVendor = await globex.post("/api/vendors", {
      data: { name: uniqueName("Globex Only"), category: "services", contact_email: "ops@globex-procurement.com" },
    });
    expect(globexVendor.status(), await globexVendor.text()).toBe(201);
    const vendorId = (await globexVendor.json()).id;

    const upload = await globex.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from("Legal Name: Globex") },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const documentId = (await upload.json()).id;

    // Act: the Northwind member requests the Globex document by id
    const response = await member.get(`/api/documents/${documentId}`);

    // Assert
    expect(response.status(), await response.text()).toBe(404);
    expect((await response.json()).error.code, await response.text()).toBe("document_not_found");
  });
});
